solution.code:
SELECT MAX(salary) AS SecondHighestSalary
FROM Employee
WHERE salary < (SELECT MAX(salary) FROM Employee);

alternativeApproaches.code:
SELECT (
  SELECT DISTINCT salary
  FROM Employee
  ORDER BY salary DESC
  LIMIT 1 OFFSET 1
) AS SecondHighestSalary;

SELECT MAX(salary) AS SecondHighestSalary
FROM (
  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS rnk
  FROM Employee
) t
WHERE rnk = 2;

solution.code:
SELECT MAX(salary) AS NthHighestSalary
FROM (
  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS rnk
  FROM Employee
) ranked
WHERE rnk = 3;

alternativeApproaches.code:
SELECT e.name AS Employee
FROM Employee e
WHERE e.salary > (SELECT m.salary FROM Employee m WHERE m.id = e.manager_id);

SELECT DISTINCT a.email
FROM Person a
JOIN Person b ON a.email = b.email AND a.id <> b.id;

SELECT email FROM (
  SELECT email, COUNT(*) OVER (PARTITION BY email) AS c
  FROM Person
) t
WHERE c > 1
GROUP BY email;

SELECT year, [1] AS q1, [2] AS q2, [3] AS q3, [4] AS q4
FROM (SELECT year, quarter, amount FROM Sales) src
PIVOT (SUM(amount) FOR quarter IN ([1], [2], [3], [4])) p;

SELECT c.name
FROM Customers c
WHERE NOT EXISTS (SELECT 1 FROM Orders o WHERE o.customer_id = c.id);

SELECT a.student AS s1, b.student AS s2, a.course
FROM Enrollment a
JOIN Enrollment b ON a.course = b.course AND a.student < b.student;

SELECT DISTINCT LEAST(user_a, user_b) AS u1, GREATEST(user_a, user_b) AS u2
FROM Friendship
WHERE user_a <> user_b;
